// Extract the full article content
const content = [];
const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, li');
headings.forEach(el => {
  if (el.tagName === 'H1') content.push('# ' + el.textContent.trim());
  else if (el.tagName === 'H2') content.push('## ' + el.textContent.trim());
  else if (el.tagName === 'H3') content.push('### ' + el.textContent.trim());
  else if (el.tagName === 'P') {
    const text = el.textContent.trim();
    if (text) content.push(text);
  }
  else if (el.tagName === 'LI') {
    const text = el.textContent.trim();
    if (text) content.push('- ' + text);
  }
});
content.join('\n\n');
